window.kbPageData["views/practice/s-4863baf2b4febcf4"] = {"key":"practice/s-4863baf2b4febcf4","state":{"route":"practice/s-4863baf2b4febcf4"},"tree":"<a data-toc-link href=\"#skills/shenlun\">申论技能首页</a><details data-branch=\"module-归纳概括\" open><summary>归纳概括</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c898afc5816920c2\">概括作用与成效</a><a data-toc-link href=\"#practice/s-0b47c7faa1dcfbc7\">提炼做法与经验</a><a data-toc-link href=\"#practice/s-75a1eb1e46268fd8\">归类概括材料中的问题</a><a data-toc-link href=\"#practice/s-4863baf2b4febcf4\" aria-current=\"page\">配对概括做法与成效</a><a data-toc-link href=\"#practice/s-c94c813ed743298a\">从材料提取概念特征</a><a data-toc-link href=\"#practice/s-4da331cba0998f2b\">分条梳理不同立场与分歧</a></div></details><details data-branch=\"module-综合分析\"><summary>综合分析</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-43e39afd29a17e74\">解释含义与作用</a><a data-toc-link href=\"#practice/s-599008555ed60dda\">分析现象形成的原因</a><a data-toc-link href=\"#practice/s-93367fee5c934df6\">从案例推导改进建议</a></div></details><details data-branch=\"module-提出对策\"><summary>提出对策</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c6bd983baf5dd3ae\">根据问题成因逐项提出措施</a><a data-toc-link href=\"#practice/s-ecba3f8c2c1d3b9b\">将外地经验转化为本地措施</a><a data-toc-link href=\"#practice/s-9b570af6b9f113ee\">按治理环节组织对策</a><a data-toc-link href=\"#practice/s-91888cb77ec12615\">从材料反馈中提炼改进建议</a></div></details><details data-branch=\"module-应用文写作\"><summary>应用文写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-171ebed39b4fe1cf\">汇报与交流发言</a><a data-toc-link href=\"#practice/s-b92b682e65d12042\">面向公众动员参与</a><a data-toc-link href=\"#practice/s-cabc6af5d656b214\">宣传介绍与活动报道</a><a data-toc-link href=\"#practice/s-5cd530a611f08110\">编写案例摘要</a><a data-toc-link href=\"#practice/s-9f175b7eb1a79028\">陈述事由与请求</a><a data-toc-link href=\"#practice/s-38dece0b54a49be3\">拟定工作事项与措施</a><a data-toc-link href=\"#practice/s-c8dfde3ede3eadab\">撰写案例短评或点评</a></div></details><details data-branch=\"module-文章写作\"><summary>文章写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-b8139af04b609dce\">展开分论点的论证</a><a data-toc-link href=\"#practice/s-4fdadcb77809c673\">围绕中心论点组织分论点</a><a data-toc-link href=\"#practice/s-ab43045e4cab9ffe\">从材料立意并确立中心论点</a></div></details>","packs":{"国考 2023 副省级 申论#1":"4888771988a40e566414f930","国考 2025 地市级 申论#2":"4888771988a40e566414f930","江苏 2023 C类 申论#1":"4888771988a40e566414f930"},"questions":{"国考 2023 副省级 申论#1":{"paper":"国考 2023 副省级 申论","n":1,"mod":"申论","src":["1b62f4f7aa551cdd783e.pdf",4],"asrc":["269b01c80926c8585ace.pdf",1]},"国考 2025 地市级 申论#2":{"paper":"国考 2025 地市级 申论","n":2,"mod":"申论","src":["16fbc0b81d8aafc9f70b.pdf",4],"asrc":["cfcf70b08272c4dfe4c2.pdf",1]},"江苏 2023 C类 申论#1":{"paper":"江苏 2023 C类 申论","n":1,"mod":"申论","src":["22d3f6f8ead61f1ba343.pdf",4],"asrc":["65862c79cc2f34940f00.pdf",1]}},"first":{"qs":{"国考 2023 副省级 申论#1":{"paper":"国考 2023 副省级 申论","n":1,"mod":"申论","src":["1b62f4f7aa551cdd783e.pdf",4],"asrc":["269b01c80926c8585ace.pdf",1],"m":["99a000462e0fa5ca"],"task":"依据材料1，分条概括玉陵湖大桥的设计、施工及通车成效体现了哪些巧处，全文不超过250字。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答所需的工程做法及其成效均由材料提供。"},"links":[{"id":"k-3039a8202fcf639d","label":"景区桥梁可借助桥型设计与自然景观相协调","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"采用提篮拱桥设计，优雅灵动，突出力量美与跨越感，与自然融为一体、相互辉映。","why":"桥型与湖山景观的协调说明了设计的审美价值。","origin":"逐题标记"},{"id":"k-972fd9bafc6801f6","label":"跨越水源保护区的桥梁可借助新拱拆除旧桥以减少生态扰动","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"M1","quote":"旧桥建新拱，新拱拆旧桥","why":"新拱辅助吊拆旧桥，可防止拆除构件落入水源保护区。","origin":"逐题标记"},{"id":"k-2fbd469d07e465b3","label":"桥梁改建可回收旧桥废料并将达标施工污水用于现场洒水","catalog_id":null,"type":"方法与技能","role":"直接考查","field":"answer","quote":"旧桥废料完全循环回收、利用，施工中污水处理达标后用于施工区域洒水。","why":"固体废料回收和达标污水回用共同体现施工中的资源节约。","origin":"逐题标记"},{"id":"k-708a85e0d7e31fbe","label":"桥路衔接设计影响行车安全与沿线村庄的通达性","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"采用“8”字形连接方式，与高速公路无缝衔接，减少交通事故，连接9个村庄，四通八达。","why":"新桥的接线方式体现了道路衔接对交通安全和村庄连通的作用。","origin":"逐题标记"},{"id":"k-3f2cab661887da7b","label":"交通可达性改善可通过促进要素流动带动沿线乡村经济","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"促进人、物、信息的流动，让附近村庄焕发出新活力，带出经济圈。","why":"材料以村庄产业和经营活动的发展说明桥梁通车带来的经济效应。","origin":"逐题标记"},{"id":"s-4863baf2b4febcf4","label":"按并列维度归纳工程做法及其成效","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"请你谈谈玉陵湖大桥“巧”在哪些地方？","why":"需要从采风叙事中提取相关做法与成效，归并为彼此并列的要点。","origin":"逐题标记"}],"stem":"“给定资料1”中，青年画家以玉陵湖大桥作画并题名为《巧》。请你谈谈玉陵湖大桥“巧”在哪些地方？（10分）\n要求：全面、准确、有条理。不超过250字。","options":[],"answer":"","analysis":"1.巧在景观优美。采用提篮拱桥设计，优雅灵动，突出力量美与跨越感，与自然融为一体、相互辉映。\n  2.巧在生态友好。采取边拆边建的改建方式，最大限度避免旧桥拆除对周边生态环境的不良影响。\n  3.巧在节约资源。采用环保技术，旧桥废料完全循环回收、利用，施工中污水处理达标后用于施工区域洒水。\n  4.巧在交通便利。采用“8”字形连接方式，与高速公路无缝衔接，减少交通事故，连接9个村庄，四通八达。\n  5.巧在带动发展。带来人气、商气、财气，促进人、物、信息的流动，让附近村庄焕发出新活力，带出经济圈。\n  参考答案说明：本参考答案从“巧在景观优美”“巧在生态友好”“巧在节约资源”“巧在交通便利”“巧在带动发展”这五\n个方面进行了分条撰写，各条答案要点之间在内容上相互并列，没有交叉。","figs":[],"state":"已标记","notes":[],"domains":["科技","生态环境","经济"],"nature":"综合题","current":false},"国考 2025 地市级 申论#2":{"paper":"国考 2025 地市级 申论","n":2,"mod":"申论","src":["16fbc0b81d8aafc9f70b.pdf",4],"asrc":["cfcf70b08272c4dfe4c2.pdf",1],"m":["efb3cb8085065b73"],"task":"依据给定资料2，按合作事项概括政府和企业各自的做法及其如何共同促成治水成效，限300字。","current_affairs":{"state":"否","event":null,"year":null,"basis":"依据给定材料即可概括政企合作过程，平台推广等时间信息用于交代案例进程。"},"links":[{"id":"k-bde662e651e1f3ae","label":"政府购买企业污染源排查服务可为治水决策提供一手资料","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"政府全面考察后购买服务，企业提供详实一手\n资料，为科学决策提供参考。","why":"政府考察后购买服务，企业以专业排查成果支持政府决策。","origin":"逐题标记"},{"id":"k-27fb2b8595135822","label":"智慧治水系统的实时预警、分送处置与试用推广","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"企业搭建智慧河道云平台，可自\n动上报河流污染情况，政府试用后在全市推广。","why":"企业研发的系统让管理人员及时收到预警，将污染信息传送给责任部门，政府通过试用推动平台推广。","origin":"逐题标记"},{"id":"k-696aaf981b65d96f","label":"聘任企业河监可用企业专业力量辅助治河执法监督","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"政府聘请企业担任“企业河监”，为企业治河提供机会，企业以专业力量助力执法监督。","why":"政府通过聘任提供参与渠道，企业为执法监督补充专业力量。","origin":"逐题标记"},{"id":"k-f6786866c10fd4e5","label":"末端截污遇暴雨失效时可从源头实施雨污分流","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"建议从源头抓起，实现雨污分流。","why":"暴雨时末端管道截不住污水，企业综合专家意见提出源头治理方案，政府论证后实施。","origin":"逐题标记"},{"id":"k-1f1005d386e9e76d","label":"政企可基于智慧河道平台实践共同制定河长制信息管理技术规程","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"以智慧河道云平台为基础，虑\n远科技还参与了新杭市“五水共治”办和埠西区“五水共治”办制定《河长制信息管理系统应用技术规程》的工作。","why":"企业参与将平台应用经验转化为技术规程，形成可公开发布的技术规范。","origin":"逐题标记"},{"id":"s-4863baf2b4febcf4","label":"按合作事项归类并配对各主体的行动与成效","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"政府与企业是如何通\n过良性互动实现成功治水的。","why":"需要把散见于材料的行动按合作事项归并，写明各方如何衔接及其产生的作用。","origin":"逐题标记","originalId":"s-5b735d380f653b96"}],"stem":"“给定资料2”介绍了虑远科技与新杭市埠西区政府合力治水的事例。请你谈谈在这一事例中，政府与企业是如何通\n过良性互动实现成功治水的。（15分）\n要求：理解准确，内容全面，逻辑清晰。不超过300字。","options":[],"answer":"","analysis":"1.合作排查水质污染源。政府发布污染排查公告，企业主动请缨，政府全面考察后购买服务，企业提供详实一手\n资料，为科学决策提供参考。\n   2.合作建设智慧系统。企业研发城市排涝指挥控制系统，政府采用并充分肯定；企业搭建智慧河道云平台，可自\n动上报河流污染情况，政府试用后在全市推广。\n   3.合作治理河流污染。政府聘请企业担任“企业河监”，为企业治河提供机会，企业以专业力量助力执法监督。\n   4.合作推进雨污分流。政府邀请企业参与治河研讨，企业综合专家意见，提交河流“雨污分流”建议，政府组织论\n证后采纳实施。\n   5.合作制定技术规程。企业参与政府制定《河长制信息管理系统应用技术规程》工作，政府在全国团体标准信息\n平台发布。\n   参考答案说明：本参考答案从“合作排查水质污染源”“合作建设智慧系统”“合作治理河流污染”“合作推进雨污分\n流”“合作制定技术规程”五个方面展开，各条答案要点之间在内容上相互并列，没有交叉。","figs":[],"state":"已标记","notes":[],"domains":["公共管理","生态环境"],"nature":"综合题","current":false},"江苏 2023 C类 申论#1":{"paper":"江苏 2023 C类 申论","n":1,"mod":"申论","src":["22d3f6f8ead61f1ba343.pdf",4],"asrc":["65862c79cc2f34940f00.pdf",1],"m":["93b657b98e105198","b2403e7f227b12ec","3d528b73eeaaf7cb","7cd8d484677ece0a"],"task":"根据材料1至4，在250字以内用一段话概括基层组织如何发挥四类人才的优势，以及由此带来的乡村新变化。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答所需的人才做法与乡村变化均由材料给出，典型案例发布属于材料背景。"},"links":[{"id":"k-8882da31629371ef","label":"村务员凭借对村情的了解开展巡查、解决公共服务问题并调解邻里纠纷","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"村务员熟乡情、接地气，在处理乡村问题的时候往往能‘四两拨千斤’","why":"本题要求概括村务员如何发挥熟悉村情的优势，改善公共服务和基层治理。","origin":"逐题标记"},{"id":"k-ba2c2dd757187b3a","label":"农业专家与村庄按产业需求结对应用科研成果，并通过实践带教和授课培养本土技术人才","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M2","quote":"专家传技术，实践育人才。","why":"参考答案将技术推广、成果转化和本土人才培养归为博士帮帮团带来的变化。","origin":"逐题标记"},{"id":"k-85ae12202aa184bb","label":"乡村规划通过征求村民意见、尊重乡土文化兼顾空间美观与实用","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M3","quote":"既避免了呆板格局，又满足了村民意愿。","why":"村民参与协商后形成的农房布局体现了设计专长与当地需求、习俗的结合。","origin":"逐题标记"},{"id":"k-df2138eab3d5fad2","label":"基层文艺志愿者通过村民自编自演和跨村巡演丰富文化生活，并通过演艺培训扩大参与队伍","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M4","quote":"自行编排节目，自行导演剧目，自发到周边村庄巡演","why":"参考答案将村民参与巡演和培训分别归纳为丰富文化生活、壮大基层文化队伍。","origin":"逐题标记"},{"id":"s-4863baf2b4febcf4","label":"按主体归类并配对做法与成效","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"各条答案要点之间在内容上相互并列，没有交叉。","why":"需逐类提取人才优势、具体做法和对应变化，再压缩成一段并列概括。","origin":"逐题标记","originalId":"s-b7f684383d818d49"}],"stem":"“给定资料1-4”中，列举了基层组织发挥各类人才的作用带来了乡村新变化，请用一段话对此加以概括。（20分）\n要求：紧扣给定资料，准确全面，条理清晰，语言流畅。篇幅不超过250字。","options":[],"answer":"","analysis":"各类人才给乡村带来新变：发挥村务员熟乡情、接地气的优势，通过巡查及时发现问题、解决问题，确保村内\n交通安全、卫生整洁，化解村民间的矛盾，提升乡村治理水平；发挥博士“帮帮团”技术优势，推广农业技术，推动农\n业成果转化，提升农业现代化水平，通过实践和教学，培养更多农业技术人才；发挥乡村规划师设计专长，将乡村\n规划与村民需求、乡土文化相结合，兼顾美观与实用，打造美丽乡村；发挥基层文艺爱好者的热情，组成志愿者团\n队，自编自演节目，开展村村巡演，丰富村民文化生活，开展演艺培训，壮大基层文化队伍。\n  参考答案说明：本参考答案按照“总结性引导语+各类人才的作用带来了乡村新变化”的结构，从“发挥村务员熟乡\n情、接地气的优势”“发挥博士‘帮帮团’技术优势”“发挥乡村规划师设计专长”“发挥基层文艺爱好者的热情”四类人才的作\n用及其带来的乡村变化展开，各条答案要点之间在内容上相互并列，没有交叉。","figs":[],"state":"已标记","notes":[],"domains":["社会治理"],"nature":"综合题","current":false}},"materialFiles":{"99a000462e0fa5ca":"de099be20f6e6ca22f16981f","efb3cb8085065b73":"d4a8d2d2c40670c36e66f5ef","93b657b98e105198":"efae2fb64dca1509c9d9caa4","b2403e7f227b12ec":"5cef9ceaf26127c91ee7d2f4","3d528b73eeaaf7cb":"616434ee1950212afce17d5c","7cd8d484677ece0a":"2f789178d7f71243c2de1870"},"terms":{"k-3039a8202fcf639d":{"id":"k-3039a8202fcf639d","mode":"k","type":"事实与事件","title":"玉陵湖大桥的提篮拱设计","qs":[],"count":1},"k-972fd9bafc6801f6":{"id":"k-972fd9bafc6801f6","mode":"k","type":"原理与机制","title":"玉陵湖大桥边建边拆","qs":[],"count":1},"k-2fbd469d07e465b3":{"id":"k-2fbd469d07e465b3","mode":"k","type":"事实与事件","title":"玉陵湖大桥废料回收与施工污水回用","qs":[],"count":1},"k-708a85e0d7e31fbe":{"id":"k-708a85e0d7e31fbe","mode":"k","type":"原理与机制","title":"玉陵湖大桥的“8”字形接线","qs":[],"count":1},"k-3f2cab661887da7b":{"id":"k-3f2cab661887da7b","mode":"k","type":"原理与机制","title":"交通通达与乡村经济发展","qs":[],"count":1},"s-4863baf2b4febcf4":{"id":"s-4863baf2b4febcf4","mode":"s","type":"归纳概括","title":"配对概括做法与成效","qs":[],"count":3},"k-bde662e651e1f3ae":{"id":"k-bde662e651e1f3ae","mode":"k","type":"事实与事件","title":"埠西区政府购买污染源排查服务","qs":[],"count":1},"k-27fb2b8595135822":{"id":"k-27fb2b8595135822","mode":"k","type":"原理与机制","title":"埠西区城市排涝控制系统与智慧河道云平台","qs":[],"count":1},"k-696aaf981b65d96f":{"id":"k-696aaf981b65d96f","mode":"k","type":"事实与事件","title":"埠西区“企业河监”","qs":[],"count":1},"k-f6786866c10fd4e5":{"id":"k-f6786866c10fd4e5","mode":"k","type":"原理与机制","title":"雨污分流","qs":[],"count":1},"k-1f1005d386e9e76d":{"id":"k-1f1005d386e9e76d","mode":"k","type":"事实与事件","title":"《河长制信息管理系统应用技术规程》的制定","qs":[],"count":1},"k-8882da31629371ef":{"id":"k-8882da31629371ef","mode":"k","type":"事实与事件","title":"龙溪村村务员","qs":[],"count":1},"k-ba2c2dd757187b3a":{"id":"k-ba2c2dd757187b3a","mode":"k","type":"事实与事件","title":"T市乡村振兴博士“帮帮团”","qs":[],"count":1},"k-85ae12202aa184bb":{"id":"k-85ae12202aa184bb","mode":"k","type":"事实与事件","title":"议堂村农房规划","qs":[],"count":1},"k-df2138eab3d5fad2":{"id":"k-df2138eab3d5fad2","mode":"k","type":"事实与事件","title":"W市“文化串门”村村巡演","qs":[],"count":1}},"questions":{}},"firstMaterials":[{"key":"99a000462e0fa5ca","value":["材料1","材料1\n  今年夏天，Q省邀请若干位全国知名的青年书法家、画家参加了一场采风活动，为这些青年名家的艺术创作提供\n现实资源，让他们用书画作品倾情反映新时代的Q省交通故事。以下是其中一位青年画家的采风日记：\n   习近平总书记曾经说，中国的交通地图就像一幅画，中国的中部、东部、东北地区都是工笔画，西部留白太大\n了，将来也要补几笔，把美丽中国的交通勾画得更美。Q省位于我国西南部，是唯一没有平原支撑的省份，交通巨变\n从“桥”开始。这次采风，我在Q省看到了最精妙的补笔。昨天，已是我们采风的最后一站。\n   我们从省会G市驾车出发，行驶40分钟左右到达玉陵湖大桥。只见一座提篮式样的大桥，横跨美丽的玉陵湖，又\n似一道斑斓的彩虹嵌入绿水青山中，浑然天成。我们走上大桥的人行步道，发现这里拍照的人不少。G市公路管理局\n的工程师秦创告诉我们，玉陵湖大桥重建以来已经成为著名的“网红打卡地”。在设计之初，考虑到玉陵湖大桥连接Q\n省多个著名旅游景区，如何使新桥融入这些湖光山色之中，是他们反复考量的内容。最终他们选择了内倾10°的提篮\n拱桥作为重建方案，这样能够使新建桥梁在景观上优雅灵动，突出桥梁自身的力量美与跨越感，同时也能让桥梁与\n自然融为一体、相互辉映。“这‘提篮彩虹’的印象，我一定要画出来。”我已经为自己的第一眼印象勾勒了画作最初的\n形象。\n  “你们现在看到的玉陵湖大桥是在原桥基础上拆除重建的。”秦创向我们介绍，“原玉陵湖大桥已经通车了30余\n年，8年前被定为四类危桥，不得不对其限载、限速。2019年我们向省公路局请示拆除重建玉陵湖大桥，先后经过了\n6个方案的对比和论证，最终决定选择现在的方案——在原址上建设新的玉陵湖大桥。建设历时两年，去年正式通\n车。”\n  “你们看，这座大桥跨越湿地公园和饮用水源保护区，周围分布着特有濒危水生植物，还有20多种国家重点保护\n野生动植物。这种环境下如何拆除旧桥？用传统的爆破法拆桥行不行？”秦创出题考我们。\n  我们纷纷摇头。秦创说：“没错，施工过程中旧桥杆件会坠落到桥下水源保护区，爆破震动还会产生较大的粉尘\n污染环境。”\n  那可以用什么方法拆除旧桥呢？秦创没有为难我们，很快公布了答案：他们没有按照常规方式先拆后建，而是\n采取了边建边拆的改建方式，创新性地提出了“旧桥建新拱，新拱拆旧桥”的建设思路。两岸接线工程对景区和水源保\n护区几乎无干扰；湖中没有设置桥墩，主桥直接跨过玉陵湖；安装新桥拱肋，先“包住”旧桥，再用钢梁将旧桥吊起，\n外科手术式地完成旧桥拆除工作……这些技术都最大限度地避免了旧桥拆除对周边生态环境的不良影响。“拆桥过程\n中，没有一块旧桥混凝土掉入湖中。”秦创骄傲地说。\n  提起建桥的过程，秦创更滔滔不绝了，他详细介绍了建桥中的“废料再利用”和“污水收集处理循环系统”这两项环\n保技术。“废料再利用”是指旧桥混凝土100%循环再利用，旧桥251吨钢材全部被回收。“污水收集处理循环系统”是指\n施工中对污水进行集中处理，达到排放标准后用于施工区域洒水。秦创把枯燥的技术讲得通俗易懂。我们听得津津\n有味，心中叹服，原来巧夺天工来自于技术的高超。\n  走了不到300米，我们就来到了桥尾。玉陵湖大桥与两条高速公路无缝连接，呈“8”字形环绕。秦创说：“桥梁和\n道路的连接处是设计的关键点，对接不好容易发生交通事故。我们在设计时与公路施工方反复沟通，最终确定了现\n在这个‘8’字形的连接方式。现在新桥能连接9个村庄，可谓四通八达。”这座小而美的桥梁，真是处处体现匠心。\n  车行10分钟后，我们来到了最近的大通村。漫步大通村，一片片绿油油的茶山令人赏心悦目；绿树下，一栋栋\n独具特色的民宿布局合理，相映成趣；农家乐里，一位位游客边赏湖景，边品美食；蔬菜基地里，一棵棵长势良好\n的蔬菜静待收获；数百亩果园里，成熟的李子、桃子等时令水果挂满枝头。“目前，我们村拥有560亩水果基地、300\n亩蔬菜基地、300亩花卉基地、80亩藕园，开设有民宿、农家乐等40余家。这是新桥为大通村引来的人气、商气、财\n气。”大通村委会林主任对新桥赞不绝口。\n  “真是桥通路通民心通。不能仅仅画桥，这焕发出新活力的村庄一定要表现出来。”我心里琢磨着。当晚，我按捺\n不住思绪，彻夜未眠，一气呵成完成了画作。作画时，我脑海中不断闪现玉陵湖大桥种种精妙绝伦之处，对建设者\n们的敬佩之意一次次油然而生。整幅画作，我选择了“俯瞰”的视角，最初打算特写的“提篮彩虹”，被我简化为画中的\n一个点，路为线，人流、物流、信息流在此间快速流动。流动中，一座桥带出了一个活力迸发的经济圈。这幅表现\n桥的画，被我题名为《巧》。",["1b62f4f7aa551cdd783e.pdf",1]],"label":"国考 2023 副省级 申论|材料1"}],"node":{"id":"s-4863baf2b4febcf4","mode":"s","title":"配对概括做法与成效","type":"归纳概括","domain":"科技","reading":"","intro":"","priority":100,"aliases":["按并列维度归纳工程做法及其成效","按合作事项归类并配对各主体的行动与成效","按主体归类并配对做法与成效"],"qs":["国考 2023 副省级 申论#1","国考 2025 地市级 申论#2","江苏 2023 C类 申论#1"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"subject":"申论","publishedSets":[{"name":"配对概括做法与成效","ids":["国考 2023 副省级 申论#1","国考 2025 地市级 申论#2","江苏 2023 C类 申论#1"],"units":[["国考 2023 副省级 申论#1"],["国考 2025 地市级 申论#2"],["江苏 2023 C类 申论#1"]]}]}};
